 }

code.VVToken.isConfirmed(bytes32):
function isConfirmed(bytes32 TransHash) public constant returns (bool){
 uint count = 0;
 for (uint i=0; i<owners.length; i++)
 if (Confirmations[TransHash][owners[i]])
 count += 1;
 if (count == ownerRequired)
 return true;
 }

